import React, { useState } from 'react';
import './Dashboard.css';

const Dashboard = ({ userRoles }) => {
    const [activeAudio, setActiveAudio] = useState(null);
    const [audioPlayer, setAudioPlayer] = useState(null);

    const importantMaterials = [
        { id: 1, title: "О стремлении человека не есть", description: "Понимание истинных потребностей тела и духа" },
        { id: 2, title: "Основа сила человека - дух", description: "Как развивать духовную силу" },
        { id: 3, title: "Значение движения", description: "Почему движение - это жизнь" },
        { id: 4, title: "Дыхание - основа жизни человека", description: "Практики правильного дыхания" },
        { id: 5, title: "О силе человека", description: "Источники внутренней силы" }
    ];

    const broadcasts = [
        { id: 1, title: "Эфир - 01.01.2025", date: "1 января 2025", audioUrl: "/audio/efir-01-01-2025.mp3" },
        { id: 2, title: "Эфир - 13.01.2025", date: "13 января 2025", audioUrl: "/audio/efir-13-01-2025.mp3" },
        { id: 3, title: "Эфир - 22.01.2025", date: "22 января 2025", audioUrl: "/audio/efir-22-01-2025.mp3" },
        { id: 4, title: "Эфир - 31.01.2025", date: "31 января 2025", audioUrl: "/audio/efir-31-01-2025.mp3" }
    ];

    const channels = [
        { name: "Путь Сердца", type: "Главный канал", link: "#" },
        { name: "Путь Сердца - Чат", type: "Прикрепленная группа для общения", link: "#" },
        { name: "Эволюция Питания (Путь Сердца)", type: "Канал по питанию", link: "#" }
    ];

    const handlePlayAudio = (broadcast) => {
        if (audioPlayer) {
            audioPlayer.pause();
        }

        const audio = new Audio(broadcast.audioUrl);
        setAudioPlayer(audio);
        setActiveAudio(broadcast.id);

        audio.play();
        audio.onended = () => {
            setActiveAudio(null);
            setAudioPlayer(null);
        };
    };

    const handleStopAudio = () => {
        if (audioPlayer) {
            audioPlayer.pause();
            setAudioPlayer(null);
            setActiveAudio(null);
        }
    };

    return (
        <div className="dashboard">
